sources=[]; keys={}
for n,(key,kind,title,scope,selected_pages) in enumerate(source_specs,1):
    d=ledger[key].copy(); sid=f'R4E-{n:03d}'; keys[key]=sid
    p=Path(d['path']); assert p.is_file()
    d.update(source_id=sid,source_class=kind,title=title,review_scope=scope,usable=True,sha256=hashlib.sha256(p.read_bytes()).hexdigest(),bytes=p.stat().st_size)
    d['path']=str(p)
    d['local_file']=str(p)
    d['acceptance_role']=('candidate_only_do_not_import_exact_day' if kind=='secondary_candidate' else 'contemporary_reprint_context_not_registry_identity_proof' if kind=='primary_derived_reprint' else 'corroborating_historical_edition_not_new_event_date' if kind in ['official_historical_consolidation','official_legislative_table'] else 'direct_primary_evidence_for_scoped_claims')
    if key=='hydro1964-ar':d['text_path']=str(RAW/'hydro1964-ar-ocr.txt')
    if key=='ldb1977-hansard':d['text_path']=str(RAW/'ldb1977-hansard.txt')
    if selected_pages:
        dest=OUT/f'{sid}-{key}-selected-pages.pdf'; reader=PdfReader(p);writer=PdfWriter()
        for page in selected_pages:writer.add_page(reader.pages[page-1])
        with dest.open('wb') as f:writer.write(f)
        d['package_evidence_kind']='unaltered_page_content_extracted_from_original_pdf'
        d['package_pdf_page_map']=[{'package_page':i+1,'original_pdf_page':pg} for i,pg in enumerate(selected_pages)]
    else:
        dest=OUT/f'{sid}-{p.name}';shutil.copy2(p,dest)
        d['package_evidence_kind']='exact_downloaded_original'
    d['package_evidence_path']=str(dest)
    d['package_evidence_sha256']=hashlib.sha256(dest.read_bytes()).hexdigest()
    sources.append(d)

claims=[]
def claim(subject,predicate,text,date,source_keys,locator,wanted=('E2','E8'),precision='day',confidence='high',kind='direct',caveat='',**extra):
    c=dict(claim_id=f'R4E-C{len(claims)+1:03d}',subject=subject,predicate=predicate,claim=text,date=date,date_precision=precision,source_ids=[keys[k] for k in source_keys],source_keys=source_keys,locator=locator,wanted_items=list(wanted),confidence=confidence,evidence_type=kind,caveat=caveat)
    c.update(extra);claims.append(c);return c['claim_id']

