claim('British Columbia Electric Company Limited and British Columbia Power Commission','amalgamation_authorized','OIC 2386/1965 approves their amalgamation with the 1964 Hydro authority, with effectiveness to be set in the parties’ agreement.','1965-08-20',['oic2386-1965'],'Pages 1–2',wanted=('E10',),caveat='This is the authorizing instrument; the agreement provides the exact effective time.',date_kind='amalgamation_authorization')
claim('British Columbia Electric Company Limited and British Columbia Power Commission','ceased_separate_existence_by_amalgamation','The agreement reproduced in the Power Measures Act 1966 takes effect at 5 p.m. local Vancouver time on 20 August 1965. The three bodies continue as the Hydro authority established under the 1964 Act, and BC Electric and the Power Commission cease separate corporate existence.','1965-08-20',['oic2386-1965','power1966-measures'],'1966 Act s3 and Schedule clauses 1–2, printed pp241–242',wanted=('E2','E8','E10'),caveat='The ratifying Act assented on 1 April 1966 expressly validates the 20 August 1965 agreement. Do not date the amalgamation to the later assent.',date_kind='amalgamation_effective_datetime',local_time='17:00 local time, Vancouver',ratifying_act_assent='1966-04-01',successor='British Columbia Hydro and Power Authority established by the 1964 Act')
