claim('British Columbia Electric Company Limited','common_shares_cancelled_upon_amalgamation','Power Measures Act 1966 section 5 deems the Crown-held BC Electric common shares surrendered to Hydro and cancelled immediately upon the amalgamation.','1965-08-20',['power1966-measures'],'Section 5 and Schedule clause 2',wanted=('E2','E10'),caveat='Statutory retroactive confirmation, assented to 1 April 1966.',date_kind='retroactively_confirmed_share_cancellation')

