# Preserve unsuccessful-response classification instead of silently counting downloads as sources.
discovery=[]
for key,d in ledger.items():
    if key in keys:continue
    e=d.copy()
    if key in ['accounts1975-original','accounts1975-record']:
        e['status']='unusable_access_response';e['reason']='HTML unusual-activity block, not the requested original/API response; not bypassed.'
    elif key in ['oic1978-index','oic1980-index']:
        e['status']='unusable_empty_index_response'
    else:e['classification']='discovery_only_not_used_for_curated_claim'
    discovery.append(e)
(ROOT/'discovery_ledger.json').write_text(json.dumps(discovery,ensure_ascii=False,indent=2)+'\n')

